      "id": "a1-liegen",
      "layout": "standardStudy",
      "translation": "Atrasties • Escuna",
      "explanation": [
        "Adestramento Galvenā: lie nozīmē atrasties vai gulēt horizontaltāli.",
        "Por cilvēku lie bieži nozīmē gulēt.",
        "Per letu lie nozīmē, ka tā atrodas kaut kur.",
        "Essas atšⅡiras não esvaziam, kas nozīmē nolikt kaut ko."
      ],
      "examples": [
        {
          "de": "Das Buch liegt auf dem Tisch.",
          "lv": "Gramata atrodas uz galda."
        },
        {
          "de": "Mein Handy liegt im Auto.",
          "lv": "O telefone do homem atrodas automašīnā."
        },
        {
          "de": "Er liegt im Bett.",
          "lv": "Viņš guų gultā."
        },
        {
          "de": "Ich lege das Buch auf den Tisch.",
          "lv": "É nolieku gramatu uz galda."
        }
      ],
      "comparison": [
        {
          "word": "liegen",
          "meaning": "Atrazia/gargalo",
          "example": "Das Buch liegt hier."
        },
        {
          "word": "legen",
          "meaning": "Nolikt",
          "example": "Ich lege das Buch hierhin."
        },
        {
          "word": "stehen",
          "meaning": "Stāvēt / atrasties stāvus",
          "example": "Die Flasche steht auf dem Tisch."
        },
        {
          "word": "sein",
          "meaning": "Nós dois estamos arruinados por causa de nossas famílias.",
          "example": "Ich bin hier."
        }
      ],
      "tip": {
        "text": "Atceries: lieta jau ir vietā → liegen; tu to noliec → legen."
      },
      "important": [
        "liegen rāda stāvokli vai atrašanās vietu.",
        "legen rāda darbību: kāds kaut ko noliek."
      ],
